-- Academics module: permissions, row-level security, audit, same-school
-- references, closed-term lock and the rules the database can enforce by itself.
-- (Existing subjects and assignments are moved in the next migration.)
-- ═════════════════════════════════════════════════════════════════════════════

-- ── Permission keys ─────────────────────────────────────────────────────────
INSERT INTO "Permission" ("key", "module", "description") VALUES
  ('academics.classes.view',           'academics', 'View classes and streams'),
  ('academics.classes.manage',         'academics', 'Assign class teachers, copy classes from the last term'),
  ('academics.subjects.view',          'academics', 'View subjects'),
  ('academics.subjects.manage',        'academics', 'Change departments, subjects and combinations'),
  ('academics.subjects.approve',       'academics', 'Approve changes to the subject list'),
  ('academics.student_subjects.manage','academics', 'Give students their subjects'),
  ('academics.assignments.view',       'academics', 'View teacher assignments and workload'),
  ('academics.assignments.manage',     'academics', 'Assign teachers to classes and subjects'),
  ('academics.assignments.approve',    'academics', 'Approve the term''s teacher assignments'),
  ('academics.attendance.mark',        'academics', 'Mark attendance registers'),
  ('academics.attendance.view',        'academics', 'View attendance registers and summaries'),
  ('academics.attendance.correct',     'academics', 'Correct registers older than 7 days'),
  ('academics.timetable.view',         'academics', 'View the timetable'),
  ('academics.timetable.edit',         'academics', 'Build the timetable and the bell schedule'),
  ('academics.timetable.approve',      'academics', 'Approve and publish the timetable'),
  ('academics.timetable.cover',        'academics', 'Assign cover lessons'),
  ('academics.schemes.edit',           'academics', 'Write schemes of work and records of work'),
  ('academics.schemes.approve',        'academics', 'Approve schemes of work'),
  ('academics.schemes.view',           'academics', 'View schemes and records of work'),
  ('academics.syllabus.manage',        'academics', 'Manage the syllabus topics'),
  ('academics.analytics.view',         'academics', 'View academic analytics')
ON CONFLICT ("key") DO NOTHING;

-- ── What a teacher and a class teacher may do in this module (scoped to their own classes in the code) ──
CREATE OR REPLACE FUNCTION academics_role_keys(role_key text) RETURNS text[]
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE role_key
    WHEN 'TEACHER' THEN ARRAY['academics.classes.view', 'academics.subjects.view', 'academics.assignments.view',
                              'academics.attendance.mark', 'academics.timetable.view', 'academics.schemes.edit', 'academics.schemes.view']
    WHEN 'CLASS_TEACHER' THEN ARRAY['academics.classes.view', 'academics.subjects.view', 'academics.attendance.mark',
                                    'academics.attendance.view', 'academics.timetable.view']
    ELSE ARRAY[]::text[]
  END
$$;

-- A school created from now on starts with them.
CREATE OR REPLACE FUNCTION seed_school_roles(sid text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO "RoleDefinition" ("id", "schoolId", "key", "name", "description", "isSystem", "updatedAt")
  SELECT gen_random_uuid()::text, sid, v.k, v.n, v.d, true, CURRENT_TIMESTAMP
    FROM (VALUES
      ('OWNER',           'Owner',              'Owns the school. Full access to everything.'),
      ('HEAD',            'Head',               'The head of the school. Oversees teaching, staff and finance.'),
      ('DEPUTY_HEAD',     'Deputy Head',        'Supports the head and runs day-to-day discipline and timetabling.'),
      ('ADMINISTRATOR',   'Administrator',      'Runs the system for the school: users, settings, calendar and records.'),
      ('BURSAR',          'Bursar',             'Manages fees, payments, expenses and the school accounts.'),
      ('ACCOUNTS_CLERK',  'Accounts Clerk',     'Records payments and keeps the daily accounts under the bursar.'),
      ('HR_OFFICER',      'HR Officer',         'Looks after staff records, leave and payroll.'),
      ('HOD',             'Head of Department', 'Leads a subject department and its teachers.'),
      ('TEACHER',         'Teacher',            'Teaches classes and enters marks for their subjects.'),
      ('CLASS_TEACHER',   'Class Teacher',      'Looks after one class: register, remarks and report cards.'),
      ('EXAMS_OFFICER',   'Exams Officer',      'Runs internal and ZIMSEC examinations and their results.'),
      ('LIBRARIAN',       'Librarian',          'Runs the library: books, borrowing and fines.'),
      ('BOARDING_MASTER', 'Boarding Master',    'Looks after the boarding hostels and the boarders.')
    ) AS v(k, n, d)
  ON CONFLICT ("schoolId", "key") DO NOTHING;

  -- Everyone can see the dashboard and the calendar, so every member of staff lands somewhere.
  -- Owner and Administrator may do everything. Teachers and class teachers get their own-class keys of Academics.
  INSERT INTO "RolePermission" ("id", "schoolId", "roleId", "permissionKey")
  SELECT gen_random_uuid()::text, sid, rd."id", p.k
    FROM "RoleDefinition" rd
    CROSS JOIN LATERAL unnest(
      CASE WHEN rd."key" IN ('OWNER', 'ADMINISTRATOR')
           THEN ARRAY['*', 'system.dashboard.view', 'system.calendar.view']
           ELSE ARRAY['system.dashboard.view', 'system.calendar.view'] || academics_role_keys(rd."key") END) AS p(k)
   WHERE rd."schoolId" = sid
  ON CONFLICT ("roleId", "permissionKey") DO NOTHING;
END;
$$;

-- ── Which module an audit entry belongs to ──────────────────────────────────
CREATE OR REPLACE FUNCTION audit_module(entity text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN entity IN ('Student', 'Guardian', 'StudentGuardian', 'Enrolment', 'Enrollment', 'Absence', 'House', 'ClassMove',
                    'PromotionRun', 'Intake', 'Application', 'StudentDocument', 'DisciplineIncident', 'IncidentStudent',
                    'DisciplineAction', 'MedicalProfile', 'MedicationEntry', 'SickBayVisit', 'StudentExit', 'Alumnus') THEN 'students'
    WHEN entity IN ('SubjectAssignment', 'Subject', 'Timetable', 'AcademicsSettings', 'ClassTeacher', 'Department', 'SubjectLevel',
                    'SubjectChange', 'SubjectCombination', 'SubjectCombinationItem', 'SubjectCombinationClass', 'StudentSubject',
                    'TeachingGroup', 'TeachingGroupStudent', 'TeacherAssignment', 'AssignmentSet', 'BellSchedule', 'Period', 'Room',
                    'TimetableSlot', 'TeacherAvailability', 'CoverLesson', 'AttendanceRegister', 'AttendanceEntry', 'MessageOutbox',
                    'SyllabusTopic', 'SyllabusTemplate', 'SchemeOfWork', 'SchemeWeek', 'RecordOfWork', 'LessonPlan') THEN 'academics'
    WHEN entity IN ('Mark', 'TermResult', 'ReportCard', 'MarkChange') THEN 'exams'
    WHEN entity IN ('Payment', 'Expense', 'ExpenseRequest', 'Charge', 'FeeStructure', 'Income', 'ExchangeRate') THEN 'finance'
    WHEN entity IN ('Asset', 'AssetTransfer', 'Book', 'BookCopy', 'Borrowing', 'LibraryMember') THEN 'facilities'
    ELSE 'system'
  END
$$;

-- ── Row-level security for the new tables ───────────────────────────────────
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['AcademicsSettings', 'ClassTeacher', 'Department', 'SubjectLevel', 'SubjectChange', 'SubjectCombination',
                           'SubjectCombinationItem', 'SubjectCombinationClass', 'StudentSubject', 'TeachingGroup', 'TeachingGroupStudent',
                           'TeacherAssignment', 'AssignmentSet', 'BellSchedule', 'Period', 'Room', 'Timetable', 'TimetableSlot',
                           'TeacherAvailability', 'CoverLesson', 'AttendanceRegister', 'AttendanceEntry', 'MessageOutbox',
                           'SyllabusTopic', 'SchemeOfWork', 'SchemeWeek', 'RecordOfWork', 'LessonPlan'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY school_isolation ON %I USING (app_school_ok("schoolId")) WITH CHECK (app_school_ok("schoolId"))', t);
  END LOOP;
END $$;

-- ── Row-change audit ────────────────────────────────────────────────────────
