-- ── A closed term is read-only ──────────────────────────────────────────────
-- Everything academic that belongs directly to a term refuses changes once the term is CLOSED (the Director can
-- reopen a term). Child rows (slots, entries, weeks) are guarded by the services through their parent.
CREATE OR REPLACE FUNCTION academics_closed_term_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  tid   text := COALESCE(to_jsonb(NEW), to_jsonb(OLD)) ->> 'termId';
  tname text;
  saved text := current_setting('app.school_id', true);
BEGIN
  IF tid IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  PERFORM set_config('app.school_id', '', true);
  SELECT "name" INTO tname FROM "AcademicTerm" WHERE "id" = tid AND "status" = 'CLOSED';
  PERFORM set_config('app.school_id', coalesce(saved, ''), true);
  IF tname IS NOT NULL THEN
    RAISE EXCEPTION '% is closed, so this cannot be changed', tname USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE TRIGGER "closed_term_ClassTeacher"       BEFORE INSERT OR UPDATE OR DELETE ON "ClassTeacher"       FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_StudentSubject"     BEFORE INSERT OR UPDATE OR DELETE ON "StudentSubject"     FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_TeachingGroup"      BEFORE INSERT OR UPDATE OR DELETE ON "TeachingGroup"      FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_TeacherAssignment"  BEFORE INSERT OR UPDATE OR DELETE ON "TeacherAssignment"  FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_AssignmentSet"      BEFORE INSERT OR UPDATE OR DELETE ON "AssignmentSet"      FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_Timetable"          BEFORE INSERT OR UPDATE OR DELETE ON "Timetable"          FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_AttendanceRegister" BEFORE INSERT OR UPDATE OR DELETE ON "AttendanceRegister" FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();
CREATE TRIGGER "closed_term_SchemeOfWork"       BEFORE INSERT OR UPDATE OR DELETE ON "SchemeOfWork"       FOR EACH ROW EXECUTE FUNCTION academics_closed_term_guard();

-- ── Rules the database keeps by itself ──────────────────────────────────────
ALTER TABLE "Subject"
  ADD CONSTRAINT "Subject_colour_hex" CHECK ("colour" ~ '^#[0-9A-Fa-f]{6}$');
ALTER TABLE "AcademicsSettings"
  ADD CONSTRAINT "AcademicsSettings_subject_counts" CHECK ("minSubjectsOLevel" >= 0 AND "maxSubjectsOLevel" >= "minSubjectsOLevel" AND "minSubjectsALevel" >= 0 AND "maxSubjectsALevel" >= "minSubjectsALevel"),
  ADD CONSTRAINT "AcademicsSettings_load" CHECK ("maxPeriodsPerWeek" BETWEEN 1 AND 80),
  ADD CONSTRAINT "AcademicsSettings_alerts" CHECK ("consecutiveAbsentDays" BETWEEN 1 AND 30 AND "attendanceThresholdPct" BETWEEN 1 AND 100);
ALTER TABLE "Room"
  ADD CONSTRAINT "Room_capacity_positive" CHECK ("capacity" > 0);
ALTER TABLE "TeacherAssignment"
  ADD CONSTRAINT "TeacherAssignment_class_or_group" CHECK (("classId" IS NULL) <> ("groupId" IS NULL)),
  ADD CONSTRAINT "TeacherAssignment_periods" CHECK ("periodsPerWeek" BETWEEN 1 AND 60 AND "doublesPerWeek" >= 0 AND "doublesPerWeek" * 2 <= "periodsPerWeek"),
  ADD CONSTRAINT "TeacherAssignment_dates" CHECK ("endDate" IS NULL OR "endDate" >= "startDate"),
  ADD CONSTRAINT "TeacherAssignment_ended_has_date" CHECK ("status" <> 'ENDED' OR "endDate" IS NOT NULL),
  ADD CONSTRAINT "TeacherAssignment_two_teachers" CHECK ("coTeacherId" IS NULL OR "coTeacherId" <> "teacherId");
ALTER TABLE "AssignmentSet"
  ADD CONSTRAINT "AssignmentSet_approved_has_approver" CHECK ("status" <> 'APPROVED' OR ("approvedById" IS NOT NULL AND "approvedAt" IS NOT NULL));
ALTER TABLE "Period"
  ADD CONSTRAINT "Period_day" CHECK ("dayOfWeek" BETWEEN 1 AND 6),
  ADD CONSTRAINT "Period_number" CHECK ("periodNo" >= 1),
  ADD CONSTRAINT "Period_times" CHECK ("start" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' AND "end" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' AND "end" > "start");
ALTER TABLE "Timetable"
  ADD CONSTRAINT "Timetable_published_is_approved" CHECK ("status" NOT IN ('PUBLISHED', 'SUPERSEDED') OR ("approvedById" IS NOT NULL AND "effectiveFrom" IS NOT NULL));
ALTER TABLE "TimetableSlot"
  ADD CONSTRAINT "TimetableSlot_double_has_pair" CHECK (NOT "isDouble" OR "pairId" IS NOT NULL);
ALTER TABLE "CoverLesson"
  ADD CONSTRAINT "CoverLesson_different_teacher" CHECK ("absentTeacherId" <> "coverTeacherId");
ALTER TABLE "AttendanceRegister"
  ADD CONSTRAINT "AttendanceRegister_lesson_has_slot" CHECK (("session" = 'LESSON') = ("slotId" IS NOT NULL)),
  ADD CONSTRAINT "AttendanceRegister_daily_has_class" CHECK ("session" = 'LESSON' OR "classId" IS NOT NULL);
ALTER TABLE "AttendanceEntry"
  ADD CONSTRAINT "AttendanceEntry_excused_has_reason" CHECK ("status" <> 'EXCUSED' OR "reason" IS NOT NULL),
  ADD CONSTRAINT "AttendanceEntry_late_has_time" CHECK ("status" <> 'LATE' OR "arrivalTime" IS NOT NULL),
  ADD CONSTRAINT "AttendanceEntry_time_format" CHECK ("arrivalTime" IS NULL OR "arrivalTime" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$');
ALTER TABLE "SchemeOfWork"
  ADD CONSTRAINT "SchemeOfWork_approved_has_approver" CHECK ("status" <> 'APPROVED' OR ("approvedById" IS NOT NULL AND "approvedAt" IS NOT NULL)),
  ADD CONSTRAINT "SchemeOfWork_returned_has_comment" CHECK ("status" <> 'RETURNED' OR ("returnComment" IS NOT NULL AND btrim("returnComment") <> ''));
ALTER TABLE "SchemeWeek"
  ADD CONSTRAINT "SchemeWeek_number" CHECK ("weekNo" >= 1);
ALTER TABLE "SubjectChange"
  ADD CONSTRAINT "SubjectChange_decided_has_decider" CHECK ("status" = 'PENDING' OR ("decidedById" IS NOT NULL AND "decidedAt" IS NOT NULL));

-- One live assignment per term, subject and class (or group). An ENDED one stays as history.
CREATE UNIQUE INDEX "TeacherAssignment_one_active_per_class" ON "TeacherAssignment"("termId", "subjectId", "classId") WHERE "status" = 'ACTIVE' AND "classId" IS NOT NULL;
CREATE UNIQUE INDEX "TeacherAssignment_one_active_per_group" ON "TeacherAssignment"("termId", "subjectId", "groupId") WHERE "status" = 'ACTIVE' AND "groupId" IS NOT NULL;
-- One timetable being written and one in force per term.
CREATE UNIQUE INDEX "Timetable_one_working_version" ON "Timetable"("termId") WHERE "status" IN ('DRAFT', 'PENDING');
CREATE UNIQUE INDEX "Timetable_one_published" ON "Timetable"("termId") WHERE "status" = 'PUBLISHED';
-- The clash rules, per timetable version: a teacher, a class and a room are in one place per period.
CREATE UNIQUE INDEX "TimetableSlot_teacher_per_period" ON "TimetableSlot"("timetableId", "periodId", "teacherId");
CREATE UNIQUE INDEX "TimetableSlot_class_per_period"   ON "TimetableSlot"("timetableId", "periodId", "classId") WHERE "classId" IS NOT NULL;
CREATE UNIQUE INDEX "TimetableSlot_room_per_period"    ON "TimetableSlot"("timetableId", "periodId", "roomId") WHERE "roomId" IS NOT NULL;
CREATE UNIQUE INDEX "TimetableSlot_lesson_once_per_period" ON "TimetableSlot"("timetableId", "assignmentId", "periodId");
-- A register is one per class, day and session (and one per lesson and day).
CREATE UNIQUE INDEX "AttendanceRegister_class_day_session" ON "AttendanceRegister"("classId", "date", "session") WHERE "slotId" IS NULL;
CREATE UNIQUE INDEX "AttendanceRegister_lesson_day" ON "AttendanceRegister"("slotId", "date") WHERE "slotId" IS NOT NULL;
-- A school keeps one default bell schedule per name; a term's own schedule is found by (termId).
CREATE UNIQUE INDEX "BellSchedule_one_per_term" ON "BellSchedule"("schoolId", "termId") WHERE "termId" IS NOT NULL;
CREATE UNIQUE INDEX "BellSchedule_one_default" ON "BellSchedule"("schoolId") WHERE "termId" IS NULL;
